import wrapt
import inspect
import six

from six.moves import zip

from collections import OrderedDict

from .exception import KeywordNotExecutedException, DecorationNotSupportedException


_MESSAGE_TEMPLATE = 'Keywords that need to be ran before {}{}: {}{}'


def keyword_control(*args, **kw):
    """Control the execution of the keywords. Store history for particular instances and modules. Check if given
    keywords were executed.

    :param string *args: Required keyword function/method name
    :param boolean ordered: Define if required keywords have to be executed in order
    :param boolean cleanable: Define if logged keyword can be cleaned by clean_history function
    """
    @wrapt.decorator
    def _real_keyword_control(function, instance=None, args=None, kw=None):
        if instance is None:
            raise DecorationNotSupportedException("Not supported decorator usage. Decorator supports only methods.")
        args_dict = _get_args_dict(function, args, kw)
        alias = args_dict.get('alias', '')
        name = _get_aliased_name(function.__name__, alias)
        aliased_demands = [_get_aliased_name(demand_name, alias) for demand_name in keyword_demands]
        store = _get_store(function)
        unpacked = _unpack(store)
        if ordered and _is_sub_seq(unpacked, aliased_demands) or not ordered and set(aliased_demands).issubset(unpacked):
            store.append((name, cleanable))
            return function(*args, **kw)
        else:
            store.append((name, cleanable))
            message = _MESSAGE_TEMPLATE.format(
                function.__name__,
                " (alias: {})".format(alias) if alias else "",
                ', '.join(keyword_demands),
                " (in order)" if ordered else ""
            )
            raise KeywordNotExecutedException(message)

    ordered = kw.get('ordered', False)
    cleanable = kw.get('cleanable', True)
    if len(args) == 1 and callable(args[0]):
        keyword_demands = []
        return _real_keyword_control(args[0])
    else:
        keyword_demands = [arg.strip() for arg in args]
        return _real_keyword_control


def clean_history(instance=None):
    """Clean keyword_control history to support different scopes than library is.

    :param object instance: Library object(self), clean function history if not given
    """
    _clean(_get_store(instance.__init__))


def _get_args_dict(function, args, kw):
    args_spec = inspect.getargspec(function)
    args_names = list(OrderedDict.fromkeys(inspect.getargspec(function)[0] + list(kw.keys())))
    if _is_method(function):
        args_names.pop(0)
    defaults = zip(args_spec.args[-len(args_spec.defaults):], args_spec.defaults) if args_spec.defaults else []
    return dict(defaults + list(zip(args_names, args)) + list(kw.items()))


def _is_method(function):
    return hasattr(function, '__self__')


def _get_aliased_name(name, alias):
    return name if not alias or _is_aliased(name) else "{}.{}".format(alias, name)


def _is_aliased(name):
    return "." in name


def _get_store(function):
    self = function.__self__
    if not hasattr(self, '_instance_store'):
        self._instance_store = []
    return self._instance_store


def _unpack(store):
    return list(zip(*store)).pop(0) if store else store


def _is_sub_seq(sequence, sub_sequence):
    sequence_iterator = iter(sequence)
    try:
        for sub_element in sub_sequence:
            while True:
                if six.next(sequence_iterator) == sub_element:
                    break
        return True
    except StopIteration:
        return False


def _clean(store):
    store[:] = filter(lambda x: not x[1], store)
